BEGIN;
DROP TABLE IF EXISTS  "public"."raster_4326_time";
CREATE TABLE "public"."raster_4326_time" ("rid" serial PRIMARY KEY,"rast" raster,"filename" text);
CREATE INDEX ON "public"."raster_4326_time" USING gist (st_convexhull("rast"));
ANALYZE "public"."raster_4326_time";
SELECT AddRasterConstraints('public','raster_4326_time','rast',TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE);
END;
alter table public.raster_4326_time add column data timestamp;
alter table public.raster_4326_time add column data_text varchar;
update public.raster_4326_time set data = replace(filename, '.png', '')::timestamp;
update public.raster_4326_time set data_text = replace(filename, '.png', '');
